// Shared setup for the secret and redaction tests: fake secret values made fresh in each test,
// the encoded forms a leaked value can take, a secret store over a fake environment, and a
// trusted project and plans that name secrets.
//
// Secrets here are random values generated by the test. No test reads the real environment.
// As SPEC-04's build notes settle:
//   - Secret, SecretStore and reveal live in contracts;
//   - environmentSecretStore(variables) resolves a secret name to the variable of the same name,
//     and gives null when there is none;
//   - leakScanner() builds the LeakScanner, which reads each listed file's bytes; the caller
//     plants the canary;
//   - a run takes the store as the optional `secrets` port; without one every reference is missing;
//   - a plan names saved browser storage state in a top-level `storageState: { secretName }`, and
//     the secret's value is the storage-state JSON.
// See docs/specs/SPEC-04-secrets-and-redaction.md.
import { randomBytes } from 'node:crypto';
import type { Secret, SecretStore } from '@revisum/contracts';
import {
  defaultRedactor, environmentSecretStore, failure, parseProject, planParser, run,
  type BrowserDriver, type ElementProbe, type Plan, type Project, type RunResult, type SecretName, type Session, type TargetId,
} from '@revisum/engine';
import { memoryArtifactStore, memoryRunEventSink, systemClock } from '../../support/memory-ports.ts';
import { authorise, trustedProjectFrom } from '../../support/policy-clearance.ts';

// The forms a leak scan looks for, as SPEC-04's Leak type names them.
export const LEAK_FORMS = ['raw', 'uri', 'base64', 'base64url', 'prefix', 'case'] as const;
export type LeakForm = (typeof LEAK_FORMS)[number];

// How much of a secret a "prefix" echo keeps: well over the minimum secret length and well under
// the whole value, as a log line that cuts a token short would.
export const PREFIX_LENGTH = 20;

// A fresh fake secret of 30 characters or more. It always holds a lower-case letter (so a case
// change shows), a character that URI encoding changes, and bytes whose base64 holds "+" or "/"
// (so its base64 and base64url forms differ).
export function fakeSecretValue(): string {
  for (;;) {
    // The closing '~?' makes the base64 form hold '+' or '/', which plain ASCII letters and digits never produce.
    const candidate = `rv${randomBytes(12).toString('base64')}/${randomBytes(6).toString('hex')}~?`;
    const base64 = Buffer.from(candidate).toString('base64');
    const changesUnderUriEncoding = encodeURIComponent(candidate) !== candidate;
    if (/[a-z]/.test(candidate) && changesUnderUriEncoding && /[+/]/.test(base64)) return candidate;
  }
}

// A fresh fake secret of exactly `length` characters, letters and digits only.
export function fakeSecretOfLength(length: number): string {
  let value = '';
  while (value.length < length) value += randomBytes(16).toString('base64').replace(/[^A-Za-z0-9]/g, '');
  return value.slice(0, length);
}

// Each encoded form of a value that a page, a log or a report could echo.
export function echoForms(value: string): Readonly<Record<Exclude<LeakForm, 'case'>, string> & { upper: string; lower: string }> {
  return {
    raw: value,
    uri: encodeURIComponent(value),
    base64: Buffer.from(value).toString('base64'),
    base64url: Buffer.from(value).toString('base64url'),
    prefix: value.slice(0, PREFIX_LENGTH),
    upper: value.toUpperCase(),
    lower: value.toLowerCase(),
  };
}

// The forms of `value` found in `text`, checked directly, without the engine's scanner.
export function echoesIn(text: string, value: string): readonly string[] {
  const forms = echoForms(value);
  const lowerText = text.toLowerCase();
  const found: string[] = [];
  for (const form of ['raw', 'uri', 'base64', 'base64url'] as const) if (text.includes(forms[form])) found.push(form);
  if (lowerText.includes(value.toLowerCase())) found.push('case');
  if (lowerText.includes(forms.prefix.toLowerCase())) found.push('prefix');
  return found;
}

// The secret name as the trusted project declares it.
export const secretName = (name: string): SecretName => name as SecretName;

// A secret store over a fake environment that the test builds.
export const fakeEnvironmentStore = (variables: Readonly<Record<string, string>>): SecretStore => environmentSecretStore(variables);

// The secret a fake environment holds under `name`; a test that cannot resolve it is broken.
export function resolvedSecret(name: string, value: string): Secret {
  const secret = fakeEnvironmentStore({ [name]: value }).resolve(secretName(name));
  if (secret === null) throw new Error(`the store did not resolve ${name}`);
  return secret;
}

// ---- A trusted project that declares secrets, and plans that name them ------------------------

export const ORIGIN = 'http://127.0.0.1:4174';
export const FAKE_TARGET = 'fake-chromium';

export const secretProjectFile = (secretNames: readonly string[]) => ({
  origins: [ORIGIN],
  limits: { stepTimeoutMilliseconds: 200 },
  secretNames,
  matrix: [{
    id: FAKE_TARGET, adapter: 'fake', engine: 'chromium', device: 'desktop-1280', locale: 'en-GB',
    timezone: 'Europe/London', colorScheme: 'light', reducedMotion: 'reduce',
  }],
});

export function secretProject(secretNames: readonly string[]): Project {
  const parsed = parseProject(secretProjectFile(secretNames));
  if (!parsed.ok) throw new Error(`bad test project: ${JSON.stringify(parsed.error)}`);
  return parsed.value;
}

// A plan that fills one field per named secret, then checks the page shows its status. `extra`
// adds top-level fields, such as `storageState`.
export const secretFillPlan = (secretNames: readonly string[], extra: Readonly<Record<string, unknown>> = {}) => ({
  ...extra,
  version: '1.1',
  meta: { featureId: 'SECRETS-1', specReference: 'specs/secrets.md', title: 'Sign in with secrets' },
  targets: [FAKE_TARGET],
  steps: [
    { type: 'navigate', url: '/' },
    ...secretNames.map((name) => ({ type: 'fill', locator: { by: 'label', label: `Field for ${name}` }, value: { secretName: name } })),
    { type: 'expect', locator: { by: 'testId', testId: 'status' }, assert: { kind: 'visible' }, criterionId: 'secrets.status-shown' },
  ],
});

export function parsedPlan(project: Project, raw: unknown): Plan {
  const parsed = planParser(project)(raw);
  if (!parsed.ok) throw new Error(`test plan rejected: ${JSON.stringify(parsed.error)}`);
  return parsed.value;
}

// Saved browser storage state as a person exports it: one session cookie and one token kept in
// local storage, both fresh fake values. `json` is the secret's value.
export function fakeStorageState(): { readonly json: string; readonly cookieValue: string; readonly tokenValue: string } {
  const cookieValue = fakeSecretValue();
  const tokenValue = fakeSecretValue();
  const json = JSON.stringify({
    cookies: [{ name: 'session', value: cookieValue, domain: '127.0.0.1', path: '/', expires: -1, httpOnly: true, secure: false, sameSite: 'Lax' }],
    origins: [{ origin: ORIGIN, localStorage: [{ name: 'auth-token', value: tokenValue }] }],
  });
  return { json, cookieValue, tokenValue };
}

// ---- Drivers that need no browser ---------------------------------------------------------------

// A driver that counts its calls and never opens a session.
export function spyDriver(): BrowserDriver & { opens: number } {
  const spy = {
    opens: 0,
    info: { id: 'fake', version: 'spy', protocol: 'none' },
    supports() { return { ok: true as const, value: true as const }; },
    async open() { spy.opens++; return failure({ reason: 'launch-failed' as const, detail: 'the spy never launches' }); },
  };
  return spy;
}

const SHOWN: ElementProbe = { count: 1, visible: true, enabled: true, text: 'Ready', value: null, sensitive: false, box: null };

// A driver whose page accepts every action and shows one status element, so a run reaches its manifest.
export function quietDriver(): BrowserDriver {
  const session: Session = {
    browser: { name: 'fake-browser', version: '1.0' },
    navigate: async () => ({ ok: true, value: undefined }),
    page: async () => ({ url: `${ORIGIN}/`, title: 'Fake' }),
    act: async () => ({ ok: true, value: undefined }),
    probe: async () => SHOWN,
    screenshot: async () => new Uint8Array([137, 80, 78, 71]),
    audit: async () => [],
    accessibilitySnapshot: async () => ({ role: 'document', name: '', children: [] }),
    blockedOrigins: () => [],
    close: async () => undefined,
  };
  return {
    info: { id: 'fake', version: '1.0', protocol: 'none' },
    supports: () => ({ ok: true, value: true }),
    open: async () => ({ ok: true, value: session }),
  };
}

// ---- Running a plan with a secret store ----------------------------------------------------------

export type SecretRun = {
  readonly result: RunResult;
  // The result and the run's event log, as JSON.
  readonly everything: string;
  readonly eventLines: string;
  readonly artifactsStored: number;
};

// Runs `plan` against a project that declares `declared`, on `driver`. The secret store reads
// `environment`; null runs with no store at all.
export async function runWithSecrets(
  declared: readonly string[], plan: unknown, environment: Readonly<Record<string, string>> | null, driver: BrowserDriver,
): Promise<SecretRun> {
  const project = secretProject(declared);
  const trusted = await trustedProjectFrom(secretProjectFile(declared));
  const events = memoryRunEventSink();
  const artifacts = memoryArtifactStore();
  const ports = { drivers: new Map([['fake', driver]]), clock: systemClock, artifacts, redactor: defaultRedactor(), events };
  const result = await run({
    plan: authorise(parsedPlan(project, plan), trusted), project, targetId: FAKE_TARGET as TargetId, baseUrl: ORIGIN,
    seed: 7, fixedTimeMilliseconds: Date.UTC(2026, 0, 1), fixtures: [], host: { platform: 'test', arch: 'test' },
  }, environment === null ? ports : { ...ports, secrets: fakeEnvironmentStore(environment) });
  const eventLines = events.read().map((event) => JSON.stringify(event)).join('\n');
  return { result, everything: JSON.stringify([result, events.read()]), eventLines, artifactsStored: artifacts.references().length };
}

// A top-level manifest field that only some runs have, read without assuming the manifest's type.
export const manifestField = (result: RunResult, field: string): unknown =>
  result.manifest === null ? undefined : Reflect.get(result.manifest, field);
